import { useId } from "react";
import "./FocusProgress.css";

export interface FocusProgressProps {
  label: string;
  elapsedMinutes: number;
  totalMinutes: number;
}

function toWholeMinutes(value: number): number {
  return Number.isFinite(value) ? Math.max(0, Math.round(value)) : 0;
}

export function FocusProgress({
  label,
  elapsedMinutes,
  totalMinutes,
}: FocusProgressProps) {
  const labelId = useId();

  const total = toWholeMinutes(totalMinutes);
  const elapsed = Math.min(toWholeMinutes(elapsedMinutes), total);
  const percent = total > 0 ? (elapsed / total) * 100 : 0;
  const valueText = `${elapsed} of ${total} minutes`;

  return (
    <div className="focus-progress">
      <div className="focus-progress__header">
        <span id={labelId} className="focus-progress__label">
          {label}
        </span>
        <span className="focus-progress__count" aria-hidden="true">
          {elapsed} / {total} min
        </span>
      </div>
      <div
        role="progressbar"
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={total}
        aria-valuenow={elapsed}
        aria-valuetext={valueText}
        className="focus-progress__track"
      >
        <div
          className="focus-progress__fill"
          style={{ width: `${percent}%` }}
        />
      </div>
    </div>
  );
}
```

