  display: grid;
  gap: 0.5rem;
}

.focus-progress__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.focus-progress__label {
  font-size: clamp(0.875rem, 0.8rem + 0.4vw, 1.125rem);
  font-weight: 600;
  color: var(--ink);
}

.focus-progress__count {
  font-size: clamp(0.8rem, 0.75rem + 0.3vw, 1rem);
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.focus-progress__track {
  height: clamp(0.5rem, 0.4rem + 0.4vw, 0.75rem);
  background: var(--axon-ahead);
  border-radius: 999px;
  overflow: hidden;
}

.focus-progress__fill {
  height: 100%;
  background: var(--myelin);
  border-radius: 999px;
  transition: width 400ms ease-out;
}

:root[data-motion="reduce"] .focus-progress__fill {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .focus-progress__fill {
    transition: none;
  }
}
